import heapq
import math
import collections
(n, k, s) = map(int, input().split())
a = list(map(int, input().split()))
alliance = [list(map(int, input().split())) for _ in range(n)]
planet = collections.defaultdict(list)
for i in range(1, k + 1):
	planet[i] = []
for (i, v) in enumerate(a):
	planet[v].append(i)
heap = [(0, a[s - 1])]
heapq.heapify(heap)
ans = {}
visited = set()
while heap:
	(dist, node) = heapq.heappop(heap)
	if node in visited:
		continue
	ans[node] = dist
	visited.add(node)
	for i in planet[node]:
		for (j, k) in enumerate(alliance[i]):
			if j + 1 not in visited and k != -1:
				heapq.heappush(heap, (k + dist, j + 1))
for i in planet:
	if i not in visited:
		ans[i] = -1
print(*[ans[v] for v in a])
